#!/usr/bin/env python3
import socket
import signal
import sys
import time
import resource

sockets = []
files = []

def signal_handler(sig, frame):
    print(f"Received signal {sig}, cleaning up...")
    for s in sockets:
        try:
            s.close()
        except:
            pass
    for f in files:
        try:
            f.close()
        except:
            pass
    sys.exit(0)

signal.signal(signal.SIGTERM, signal_handler)
signal.signal(signal.SIGINT, signal_handler)

soft, hard = resource.getrlimit(resource.RLIMIT_NOFILE)
print(f"File descriptor limit: soft={soft}, hard={hard}", flush=True)

target_fds = int(soft * 0.9)

try:
    for i in range(target_fds):
        try:
            if i % 2 == 0:
                s = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
                s.setblocking(False)
                sockets.append(s)
            else:
                f = open('/dev/null', 'r')
                files.append(f)
        except Exception as e:
            print(f"Stopped at {i} FDs: {e}", flush=True)
            break

    print(f"Exhausted FDs: {len(sockets)} sockets + {len(files)} files = {len(sockets) + len(files)} total", flush=True)

    while True:
        time.sleep(60)

except KeyboardInterrupt:
    signal_handler(signal.SIGINT, None)

#!/usr/bin/env python3
import socket
import signal
import sys
import time

sockets = []

def signal_handler(sig, frame):
    print(f"Received signal {sig}, closing {len(sockets)} sockets...")
    for s in sockets:
        try:
            s.close()
        except:
            pass
    sys.exit(0)

signal.signal(signal.SIGTERM, signal_handler)
signal.signal(signal.SIGINT, signal_handler)

ports = list(range(8000, 8101)) + [80, 443] + list(range(32768, 42768))

try:
    for i in range(10000):
        try:
            s = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
            s.setblocking(False)
            port = ports[i % len(ports)]
            try:
                s.connect(('127.0.0.1', port))
            except BlockingIOError:
                pass
            except OSError:
                pass
            sockets.append(s)
            if (i + 1) % 1000 == 0:
                print(f"Created {i+1} sockets", flush=True)
        except Exception as e:
            print(f"Error creating socket {i}: {e}", flush=True)
            break

    print(f"Total sockets created: {len(sockets)}", flush=True)
    print("Socket exhaustion active. Holding connections...", flush=True)

    while True:
        time.sleep(60)

except KeyboardInterrupt:
    signal_handler(signal.SIGINT, None)
